      "variability": "Variability (Parivartansheelta) aur Taguchi Loss Function",
      "taguchi_formula": "L(y) = k * (y - m)^2",
      "taguchi_explanation": "Japanese engineer Genichi Taguchi ne prove kiya ki quality loss sirf tab nahi hota jab product specification limits (USL ya LSL) cross karta hai, balki target value 'm' se thoda sa bhi bhatakna 'y' exponential financial loss generate karta hai. Example: Toned milk mein fat ka legal standard 3.00% hai. Agar fat 2.95% ho jaye to FSSAI compliance breach aur batch rejection hota hai (huge loss). Agar fat 3.08% pack ho jaye to consumer safety to theek hai, lekin ek 2 lakh liter/day capacity ke dairy plant ke liye 0.08% excess fat giveaway ka matlab hai annual Rs. 2.8 Crore ka direct profit loss! Isliye quality ka true objective process variability ko zero ke kareeb lana hai.",
      "p2": "Manufacturing processes mein do tarah ki variability hoti hai (Walter Shewhart model): (1) Common Cause Variation — system mein natural, unavoidable noise jo standard machine precision se aati hai; aur (2) Special Cause Variation — kisi specific, identifiable defect (jaise pasteurizer steam valve jam hona ya pouch film thickness change hona) se aati hai. Six Sigma statistical methodology ka goal overall variation ko itna control karna hai ki defect rate 3.4 defects per million opportunities (DPMO) se kam rahe.",
